            lastActionVerifiedAt: nowMs - 60000,
            lastStateReadAt: nowMs - 1000,
            poorConnectionSince: nowMs - (Config.recovery.poorConnectionGraceMs + 1000),
            deadSince: null,
            missingCoreUiSince: nowMs - (Config.recovery.missingCoreUiGraceMs + 1000),
